// Liste des flux RSS à surveiller.
const flux = [
  { source: "CNIL",                     url: "https://www.cnil.fr/fr/rss.xml" },
  { source: "ANSES - Alimentation",     url: "https://www.anses.fr/fr/theme-alimentation.rss" },
  { source: "HAS - Recommandations",    url: "https://www.has-sante.fr/feed/Rss2.jsp?id=p_3081452" },
  { source: "HAS - Dispositifs medicaux", url: "https://www.has-sante.fr/feed/Rss2.jsp?id=p_3081446" },
  // A remplacer "ORG/REPO" par depot de stack une fois figee :
  { source: "GitHub - stack (a completer)", url: "https://github.com/ORG/REPO/releases.atom" }
];
return flux.map(f => ({ json: f }));

// Filtre les articles des 7 derniers jours et construit un corpus texte
// compact, pour un seul appel IA (economique et rapide).
const items = $input.all();
const now = Date.now();
const SEPT_JOURS = 7 * 24 * 60 * 60 * 1000;

const domaineVersSource = {
  "cnil.fr": "CNIL",
  "anses.fr": "ANSES",
  "has-sante.fr": "HAS",
  "github.com": "GitHub"
};

function sourceDepuisLien(lien) {
  try {
    const host = new URL(lien).hostname.replace(/^www\./, "");
    for (const d in domaineVersSource) if (host.includes(d)) return domaineVersSource[d];
    return host;
  } catch (e) { return "Source inconnue"; }
}

const recents = items
  .map(i => i.json)
  .filter(a => {
    const t = new Date(a.isoDate || a.pubDate || 0).getTime();
    return t && (now - t) <= SEPT_JOURS;
  });

const lignes = recents.map((a, n) => {
  const src = sourceDepuisLien(a.link || "");
  const date = String(a.isoDate || a.pubDate || "").slice(0, 10);
  const extrait = String(a.contentSnippet || a.content || "")
    .replace(/\s+/g, " ").trim().slice(0, 600);
  return `### Article ${n + 1}
Source: ${src}
Date: ${date}
Titre: ${a.title || ""}
Lien: ${a.link || ""}
Extrait: ${extrait}`;
}).join("\n\n");

const fmt = ms => new Date(ms).toISOString().slice(0, 10);

return [{
  json: {
    count: recents.length,
    periode: fmt(now - SEPT_JOURS) + " -> " + fmt(now),
    corpus: lignes || "Aucun article publie dans les 7 derniers jours."
  }
}];

parameters.text:
=Tu es l'assistant de veille du projet Alimendo (application d'information nutritionnelle pour personnes atteintes d'endometriose). Tu analyses des articles collectes par flux RSS.

Periode couverte : {{ $json.periode }}
Nombre d'articles : {{ $json.count }}

TROIS AXES DE VEILLE :
- Axe A - Service d'IA integre (evolutions techniques, changelog, CGU des fournisseurs de modeles).
- Axe B - Cadre reglementaire (donnees de sante / CNIL, AI Act, allegations nutritionnelles / ANSES, dispositifs medicaux / HAS, accessibilite / RGAA).
- Axe C - Etat de l'art scientifique (endometriose, alimentation, inflammation) alimentant la base RAG.

CONSIGNES STRICTES :
1. Fonde chaque analyse UNIQUEMENT sur le texte fourni. N'invente aucune information absente des extraits.
2. Ne formule JAMAIS de conseil medical, meme implicite. Tu decris ce que dit une source, tu ne recommandes rien sur le plan sante.
3. Note la pertinence de 1 a 3 (1 = anecdotique, 2 = a surveiller, 3 = impact direct sur le projet).
4. Ne retiens dans "items" que les articles de pertinence >= 2. Liste les titres ecartes dans "ecartes".
5. Classe chaque article retenu dans l'axe A, B ou C.

Reponds EXCLUSIVEMENT par un objet JSON valide, sans texte avant ou apres, sans balises de code. Schema :
{
  "resume": "2 a 3 phrases de synthese globale de la semaine",
  "items": [
    {"axe":"A|B|C","titre":"...","source":"...","date":"AAAA-MM-JJ","lien":"...","pertinence":2,"resume":"1 a 2 phrases factuelles","impact_projet":"aucun|a surveiller|action requise"}
  ],
  "ecartes": ["titre ecarte 1","titre ecarte 2"]
}

ARTICLES :
{{ $json.corpus }}

