// Transforme la reponse JSON du modele en page HTML accessible (RGAA-friendly).
const raw = $json.text || $json.output || "";
let clean = String(raw).trim()
  .replace(/^```(?:json)?/i, "")
  .replace(/```$/, "")
  .trim();

let data = null;
try { data = JSON.parse(clean); } catch (e) { data = null; }

const esc = s => String(s ?? "")
  .replace(/&/g, "&amp;").replace(/</g, "&lt;")
  .replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const aujourdHui = new Date().toISOString().slice(0, 10);
const axeNom = {
  A: "Axe A \u2014 Service d'IA int\u00e9gr\u00e9",
  B: "Axe B \u2014 Cadre r\u00e9glementaire",
  C: "Axe C \u2014 \u00c9tat de l'art scientifique"
};
const impactLibelle = {
  "aucun": "Aucun impact",
  "\u00e0 surveiller": "\u00c0 surveiller",
  "action requise": "Action requise"
};

let corps = "";
if (!data) {
  corps = `<section><h2>Synth\u00e8se brute</h2>
  <p>Le format JSON n'a pas pu \u00eatre analys\u00e9. Contenu renvoy\u00e9 par le mod\u00e8le\u00a0:</p>
  <pre>${esc(clean)}</pre></section>`;
} else {
  corps += `<section aria-labelledby="resume-titre">
    <h2 id="resume-titre">R\u00e9sum\u00e9 de la semaine</h2>
    <p>${esc(data.resume)}</p></section>`;

  const parAxe = { A: [], B: [], C: [] };
  (data.items || []).forEach(it => {
    (parAxe[it.axe] || (parAxe[it.axe] = [])).push(it);
  });

  ["A", "B", "C"].forEach(ax => {
    const liste = parAxe[ax] || [];
    if (!liste.length) return;
    corps += `<section aria-labelledby="axe-${ax}">
      <h2 id="axe-${ax}">${esc(axeNom[ax])}</h2>`;
    liste.forEach(it => {
      corps += `<article>
        <h3>${esc(it.titre)}</h3>
        <p class="meta">
          <span>Source\u00a0: ${esc(it.source)}</span> \u2014
          <time datetime="${esc(it.date)}">${esc(it.date)}</time> \u2014
          <span class="impact">Impact\u00a0: ${esc(impactLibelle[it.impact_projet] || it.impact_projet)}</span> \u2014
          <span>Pertinence\u00a0: ${esc(it.pertinence)}/3</span>
        </p>
        <p>${esc(it.resume)}</p>`;
      if (it.lien) {
        corps += `<p><a href="${esc(it.lien)}">Consulter «\u00a0${esc(it.titre)}\u00a0» sur le site de la source</a></p>`;
      }
      corps += `</article>`;
    });
    corps += `</section>`;
  });

  if ((data.ecartes || []).length) {
    corps += `<section aria-labelledby="ecartes-titre">
      <h2 id="ecartes-titre">Articles \u00e9cart\u00e9s (hors p\u00e9rim\u00e8tre ou faible pertinence)</h2><ul>`;
    data.ecartes.forEach(t => corps += `<li>${esc(t)}</li>`);
    corps += `</ul></section>`;
  }
}

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Synth\u00e8se de veille \u2014 Alimendo \u2014 ${aujourdHui}</title>
<style>
  body { font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; max-width: 60rem; margin: 0 auto; padding: 1.5rem; color: #1a1a1a; background: #fff; line-height: 1.6; }
  h1 { font-size: 1.75rem; border-bottom: 3px solid #7a1f5c; padding-bottom: .5rem; }
  h2 { font-size: 1.3rem; margin-top: 2rem; color: #7a1f5c; }
  h3 { font-size: 1.1rem; margin-bottom: .25rem; }
  article { border-left: 4px solid #c9c9c9; padding-left: 1rem; margin: 1.25rem 0; }
  .meta { font-size: .9rem; color: #3a3a3a; margin: .25rem 0 .5rem; }
  .impact { font-weight: 600; }
  a { color: #0b4f96; }
  a:focus, a:hover { outline: 2px solid #0b4f96; outline-offset: 2px; }
  footer { margin-top: 3rem; border-top: 1px solid #ccc; padding-top: 1rem; font-size: .85rem; color: #444; }
  pre { white-space: pre-wrap; background: #f4f4f4; padding: 1rem; border-radius: 4px; }
</style>
</head>
<body>
<header>
  <h1>Synth\u00e8se de veille \u2014 Alimendo</h1>
  <p>Semaine du ${aujourdHui}. Projet \u00e9tudiant \u2014 veille technique et r\u00e9glementaire (comp\u00e9tences A3 / C6).</p>
</header>
<main>
${corps}
</main>
<footer>
  <p>Document g\u00e9n\u00e9r\u00e9 automatiquement \u00e0 partir des flux RSS surveill\u00e9s, puis relu manuellement.
  Les informations proviennent des sources cit\u00e9es ; elles ne constituent pas un conseil m\u00e9dical.</p>
</footer>
</body>
</html>`;

return [{ json: { html, fichier: `veille-${aujourdHui}.html` } }];
